#### Step 2: Configure Micro-Frontend (Remote)

Each micro-frontend exposes itself as a Module Federation remote:

**Webpack Configuration:**

```javascript
// claims-mfe/webpack.config.js
const ModuleFederationPlugin = require('webpack/lib/container/ModuleFederationPlugin');

module.exports = {
  entry: './src/index',
  mode: 'production',
  output: {
    publicPath: 'https://cdn.gainwell.com/mfe/claims/v1.2.3/',
    uniqueName: 'claimsMfe',
  },
  plugins: [
    new ModuleFederationPlugin({
      name: 'claimsMfe',
      filename: 'remoteEntry.js',
      exposes: {
        './App': './src/App',              // Main application component
        './ClaimSummary': './src/components/ClaimSummary',  // Embeddable widget
      },
      shared: {
        react: {
          singleton: true,
          requiredVersion: '^18.2.0',
          // Do NOT set eager: true in remotes (let host provide)
        },
        'react-dom': {
          singleton: true,
          requiredVersion: '^18.2.0',
        },
        'react-router-dom': {
          singleton: true,
          requiredVersion: '^6.8.0',
        },
        '@gainwell/design-system': {
          singleton: true,
          requiredVersion: '^2.0.0',
        },
      },
    }),
  ],
};
```

**Exposed Module:**

```typescript
