import React from 'react';
import { Routes, Route } from 'react-router-dom';
import { ClaimsSearch } from './pages/ClaimsSearch';
import { ClaimDetail } from './pages/ClaimDetail';

export default function ClaimsApp({ context }) {
  return (
    <Routes>
      <Route path="/" element={<ClaimsSearch context={context} />} />
      <Route path="/:claimId" element={<ClaimDetail context={context} />} />
    </Routes>
  );
}
```

**Embeddable Widget:**

```typescript
// claims-mfe/src/components/ClaimSummary.tsx
import React from 'react';
import { useClaimData } from '../hooks/useClaimData';

export function ClaimSummary({ claimId }: { claimId: string }) {
  const { data, loading, error } = useClaimData(claimId);

  if (loading) return <Spinner />;
  if (error) return <ErrorMessage error={error} />;

  return (
    <div>
      <h3>Claim {data.claimNumber}</h3>
      <p>Amount: ${data.amount}</p>
      <p>Status: {data.status}</p>
    </div>
  );
}
