#### Step 4: Module Loading and Error Handling

**Lazy Loading with Fallback:**

```typescript
// shell/src/components/MicroFrontend.tsx
import React, { lazy, Suspense, ComponentType } from 'react';
import { ErrorBoundary } from 'react-error-boundary';

interface MicroFrontendProps {
  name: string;
  fallback?: React.ReactNode;
  context: MfeContext;
}

export function MicroFrontend({ name, fallback, context }: MicroFrontendProps) {
  const Module = lazy(() => loadRemoteModule(name));

  return (
    <ErrorBoundary
      fallback={<ErrorFallback />}
      onError={(error) => {
        console.error(`Failed to load ${name}:`, error);
        // Report to error tracking (Sentry, DataDog)
      }}
    >
      <Suspense fallback={fallback || <LoadingSpinner />}>
        <Module context={context} />
      </Suspense>
    </ErrorBoundary>
  );
}

function ErrorFallback({ error }: { error: Error }) {
  return (
    <div role="alert" aria-live="assertive">
      <h2>Unable to load module</h2>
      <p>{error.message}</p>
      <button
        onClick={() => window.location.reload()}
        aria-label="Retry loading the module"
      >
        Retry Loading
      </button>
    </div>
  );
}
```

**Accessible Loading States:**

```typescript
// Accessible loading indicator for lazy-loaded modules
function LoadingSpinner() {
  return (
    <div
      role="status"
      aria-live="polite"
      aria-label="Loading module content"
      className="loading-spinner"
    >
      <div className="spinner-icon" aria-hidden="true" />
      <span className="visually-hidden">Loading, please wait...</span>
    </div>
  );
}
```

**Focus Management Across Modules:**

```typescript
// shell/src/components/MicroFrontend.tsx with enhanced accessibility
import React, { lazy, Suspense, useEffect, useRef } from 'react';
import { ErrorBoundary } from 'react-error-boundary';
import { useNavigationType } from 'react-router-dom';

export function MicroFrontend({ name, context }: MicroFrontendProps) {
  const Module = lazy(() => loadRemoteModule(name));
  const containerRef = useRef<HTMLDivElement>(null);
  const navigationType = useNavigationType();

  useEffect(() => {
    // Announce module load to screen readers
    const announcement = document.createElement('div');
    announcement.setAttribute('role', 'status');
    announcement.setAttribute('aria-live', 'polite');
    announcement.setAttribute('aria-atomic', 'true');
    announcement.textContent = `${name} module loaded`;
    announcement.className = 'visually-hidden';
    document.body.appendChild(announcement);

    // Focus management: move focus to module container after load
    const timeoutId = setTimeout(() => {
      if (containerRef.current && navigationType === 'PUSH') {
        // Only move focus on new navigation, not back/forward
        containerRef.current.focus();
      }
    }, 100);

    return () => {
      clearTimeout(timeoutId);
      if (announcement.parentNode) {
        announcement.parentNode.removeChild(announcement);
      }
    };
  }, [name, navigationType]);

  return (
    <div
      ref={containerRef}
      tabIndex={-1}
      aria-labelledby={`${name}-heading`}
      role="region"
      aria-label={`${name} module content`}
      className="mfe-container"
    >
      <ErrorBoundary
        fallback={<ErrorFallback />}
        onError={(error) => {
          console.error(`Failed to load ${name}:`, error);
          // Report to error tracking (Sentry, DataDog)
        }}
      >
        <Suspense fallback={<LoadingSpinner />}>
          <Module context={context} />
        </Suspense>
      </ErrorBoundary>
    </div>
  );
}
```

**CSS for Visually Hidden Content:**

