#### Step 6: PHI Protection and Secure State Management

**PHI Isolation Pattern:**

```typescript
// claims-mfe/src/hooks/useClaimData.ts
import { useState, useEffect } from 'react';
import { fetchClaimById } from '../api/claimsApi';

// ✅ CORRECT: PHI fetched at runtime from authenticated API
export function useClaimData(claimId: string) {
  const [claimData, setClaimData] = useState<ClaimData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    let isMounted = true;

    async function loadClaim() {
      try {
        setLoading(true);
        // PHI fetched from backend with authentication token
        const data = await fetchClaimById(claimId);

        if (isMounted) {
          setClaimData(data); // PHI in component state only
        }
      } catch (err) {
        if (isMounted) {
          // ✅ CORRECT: Sanitize error - no PHI in error logs
          setError(new Error('Failed to load claim'));
          console.error('Claim load error:', { claimId }); // Log ID only, no PHI
        }
      } finally {
        if (isMounted) {
          setLoading(false);
        }
      }
    }

    loadClaim();

    // Cleanup: Clear PHI from memory when component unmounts
    return () => {
      isMounted = false;
      setClaimData(null); // Clear PHI from state
    };
  }, [claimId]);

  return { claimData, loading, error };
}
```

**❌ ANTI-PATTERN: PHI in Module Bundles:**

```typescript
// ❌ NEVER DO THIS: PHI embedded in source code
const testPatientData = {
  ssn: '123-45-6789',              // ❌ PHI violation
  name: 'John Doe',                // ❌ PHI violation
  diagnosis: 'Type 2 Diabetes',    // ❌ PHI violation
};

// ❌ NEVER DO THIS: PHI in configuration files committed to Git
const config = {
  defaultPatientId: 'PAT-12345',  // ❌ Even IDs can be PHI
  testMemberSSN: '987-65-4321',   // ❌ HIPAA violation
};
```

**Cross-Module Communication Without PHI:**

```typescript
// ✅ CORRECT: Pass opaque identifiers, not PHI
context.events.publish('claim.submitted', {
  claimId: 'CLM-123456',          // ✅ OK: Opaque identifier
  memberId: 'MEM-789',            // ✅ OK: Opaque identifier
  timestamp: Date.now(),           // ✅ OK: Non-PHI metadata
  // ❌ NEVER include: memberSSN, memberName, diagnosisCodes, providerNPI
});

// Receiving module fetches PHI from backend using IDs
context.events.subscribe('claim.submitted', async (event) => {
  // ✅ CORRECT: Fetch PHI from authenticated backend
  const memberDetails = await fetchMemberById(event.memberId);
  // Now have PHI in isolated module state
});
```

**Secure Error Logging:**

```typescript
// ✅ CORRECT: Sanitize PHI from error messages
function sanitizeError(error: Error, context: { claimId?: string; memberId?: string }) {
  // Log opaque identifiers, not PHI
  return {
    message: error.message,
    claimId: context.claimId,     // ✅ OK: Opaque ID
    memberId: context.memberId,   // ✅ OK: Opaque ID
    timestamp: new Date().toISOString(),
    // ❌ NEVER log: SSN, names, diagnoses, provider details
  };
}

try {
  await submitClaim(claimData);
} catch (error) {
  const sanitized = sanitizeError(error, { claimId: claim.id });
  console.error('Claim submission failed:', sanitized);

  // Send to monitoring (Sentry, DataDog) with sanitized data only
  Sentry.captureException(error, {
    contexts: { claim: sanitized },
  });
}
```

**Memory Cleanup on Module Unmount:**

```typescript
// claims-mfe/src/App.tsx
import { useEffect } from 'react';

export default function ClaimsApp({ context }: MfeProps) {
  useEffect(() => {
    // Module lifecycle management

    return () => {
      // ✅ CRITICAL: Clear PHI from memory on unmount
      // Clear Redux store if used
      store.dispatch(clearAllClaimData());

      // Clear any cached data
      claimCache.clear();

      // Remove event listeners that might hold PHI references
      context.events.unsubscribeAll();

      // Force garbage collection opportunity
      console.log('Claims module unmounted - PHI cleared');
    };
  }, []);

  return <ClaimsRoutes />;
}
