**Session Timeout PHI Cleanup:**

```typescript
// shell/src/auth/SessionManager.tsx
import { useEffect } from 'react';

export function SessionManager({ children }: { children: React.ReactNode }) {
  useEffect(() => {
    function handleSessionTimeout() {
      // ✅ CRITICAL: Clear all PHI on session timeout

      // Unmount all micro-frontend modules
      Object.keys(loadedModules).forEach((moduleName) => {
        unloadModule(moduleName);
      });

      // Clear browser storage
      sessionStorage.clear();
      localStorage.removeItem('lastActivity');

      // Clear Redux/Zustand global state
      store.dispatch(resetAllState());

      // Redirect to login
      window.location.href = '/login?reason=session_timeout';
    }

    // Check session timeout every 30 seconds
    const intervalId = setInterval(() => {
      const lastActivity = localStorage.getItem('lastActivity');
      const now = Date.now();
      const timeout = 15 * 60 * 1000; // 15 minutes

      if (lastActivity && now - parseInt(lastActivity) > timeout) {
        handleSessionTimeout();
      }
    }, 30000);

    return () => clearInterval(intervalId);
  }, []);

  return <>{children}</>;
}
```

