// webpack.config.js - Webpack plugin to detect PHI patterns
const WebpackPHIDetectionPlugin = {
  apply(compiler) {
    compiler.hooks.emit.tapAsync('PHIDetectionPlugin', (compilation, callback) => {
      // Scan all generated chunks for PHI patterns
      const phiPatterns = [
        /\b\d{3}-\d{2}-\d{4}\b/g,  // SSN pattern
        /\b[A-Z]{2}\d{7}\b/g,       // Member ID pattern (if PHI)
        /diagnosis["']?\s*:/gi,     // Diagnosis field
        /patient[Nn]ame/gi,         // Patient name field
      ];

      Object.keys(compilation.assets).forEach((filename) => {
        if (filename.endsWith('.js')) {
          const source = compilation.assets[filename].source();

          phiPatterns.forEach((pattern) => {
            if (pattern.test(source)) {
              compilation.errors.push(
                new Error(`Potential PHI detected in bundle: ${filename}`)
              );
            }
          });
        }
      });

      callback();
    });
  },
};

module.exports = {
  plugins: [
    WebpackPHIDetectionPlugin,
