// shell/src/moduleFederation/loadRemoteWithSRI.ts
interface RemoteConfig {
  name: string;
  url: string;
  sriHash: string;  // SHA-384 hash
}

export async function loadRemoteWithSRI(config: RemoteConfig): Promise<any> {
  return new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = config.url;
    script.type = 'text/javascript';
    script.async = true;

    // ✅ CRITICAL: Verify script integrity
    script.integrity = config.sriHash;
    script.crossOrigin = 'anonymous';

    script.onload = () => {
      // Module Federation runtime loads the module
      const container = (window as any)[config.name];
      if (!container) {
        reject(new Error(`Module ${config.name} failed to register`));
        return;
      }

      // Initialize container and load module
      container.init(__webpack_share_scopes__.default);
      container.get('./App').then((factory: any) => {
        resolve(factory());
      }).catch(reject);
    };

    script.onerror = () => {
      reject(new Error(`Failed to load remote module: ${config.name}`));
    };

    document.head.appendChild(script);
  });
}

