```typescript
// shell/src/auth/AuthenticationService.ts
import { AuthorizationServiceConfiguration, AuthorizationRequest } from '@openid/appauth';
import { generateCodeVerifier, generateCodeChallenge } from './pkce';

interface AuthTokens {
  accessToken: string;
  idToken: string;
  refreshToken: string;
  expiresAt: number;
}

export class AuthenticationService {
  private authConfig!: AuthorizationServiceConfiguration;
  private readonly clientId = 'gainwell-medicaid-app';
  private readonly redirectUri = window.location.origin + '/auth/callback';
  private readonly scope = 'openid profile email claims.read provider.read';

  async init(): Promise<void> {
    // Fetch OAuth2 configuration from Identity Provider
    this.authConfig = await AuthorizationServiceConfiguration.fetchFromIssuer(
      'https://auth.gainwell.com'
    );
  }

  async login(): Promise<void> {
    // Generate PKCE (Proof Key for Code Exchange) parameters
    const codeVerifier = generateCodeVerifier();
    const codeChallenge = await generateCodeChallenge(codeVerifier);
    const state = this.generateSecureRandomString(32);

    // Store PKCE verifier and state for callback validation
    sessionStorage.setItem('pkce_code_verifier', codeVerifier);
    sessionStorage.setItem('oauth_state', state);

    // Build authorization request
    const request = new AuthorizationRequest({
      client_id: this.clientId,
      redirect_uri: this.redirectUri,
      scope: this.scope,
      response_type: 'code',
      state: state,
      code_challenge: codeChallenge,
      code_challenge_method: 'S256',
    });

    // Redirect to authorization server
    const authUrl = this.authConfig.authorizationEndpoint + '?' + request.toQueryString();
    window.location.href = authUrl;
  }

  async handleCallback(): Promise<AuthTokens> {
    const urlParams = new URLSearchParams(window.location.search);
    const code = urlParams.get('code');
    const state = urlParams.get('state');
    const error = urlParams.get('error');

    // Handle authorization errors
    if (error) {
      throw new Error(`Authorization failed: ${error}`);
    }

    if (!code || !state) {
      throw new Error('Missing authorization code or state parameter');
    }

    // ✅ CRITICAL: Verify state to prevent CSRF attacks
    const storedState = sessionStorage.getItem('oauth_state');
    if (state !== storedState) {
      throw new Error('Invalid state parameter - possible CSRF attack');
    }

    // Retrieve PKCE code verifier
    const codeVerifier = sessionStorage.getItem('pkce_code_verifier');
    if (!codeVerifier) {
      throw new Error('Missing PKCE code verifier');
    }

    // Exchange authorization code for tokens
    const tokenResponse = await fetch(this.authConfig.tokenEndpoint, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: new URLSearchParams({
        grant_type: 'authorization_code',
        code: code,
        redirect_uri: this.redirectUri,
        client_id: this.clientId,
        code_verifier: codeVerifier,
      }),
    });

    if (!tokenResponse.ok) {
      throw new Error('Token exchange failed');
    }

    const tokens = await tokenResponse.json();

    // Store tokens securely (httpOnly cookies preferred, or encrypted sessionStorage)
    const authTokens: AuthTokens = {
      accessToken: tokens.access_token,
      idToken: tokens.id_token,
      refreshToken: tokens.refresh_token,
      expiresAt: Date.now() + (tokens.expires_in * 1000),
    };

    // Clear PKCE parameters
    sessionStorage.removeItem('pkce_code_verifier');
    sessionStorage.removeItem('oauth_state');

    return authTokens;
  }

  private generateSecureRandomString(length: number): string {
    const charset = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~';
    const randomValues = new Uint8Array(length);
    crypto.getRandomValues(randomValues);
    return Array.from(randomValues)
      .map(x => charset[x % charset.length])
      .join('');
  }
}
