// shell/src/utils/loadRemoteModule.ts
async function loadRemoteModuleWithRetry(
  name: string,
  maxRetries = 3,
  retryDelay = 1000
): Promise<any> {
  let lastError;

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      return await import(/* webpackIgnore: true */ `${name}/App`);
    } catch (error) {
      lastError = error;
      console.warn(`Failed to load ${name} (attempt ${attempt}/${maxRetries}):`, error);

      if (attempt < maxRetries) {
        await new Promise(resolve => setTimeout(resolve, retryDelay * attempt));
      }
    }
  }

  throw new Error(`Failed to load ${name} after ${maxRetries} attempts: ${lastError}`);
}
